#define _POSIX_C_SOURCE 200809L
#include <pthread.h>
#include <time.h>
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// A thread function designed to consume CPU time
void *thread_func(void *arg) {
    long long count = 0;
    // Busy loop to ensure measurable CPU time usage
    for (int i = 0; i < 500000000; ++i) {
        count += i * 2;
    }
    return NULL;
}

int main() {
    pthread_t worker_thread;
    clockid_t thread_clock_id;
    struct timespec ts_start, ts_end;
    int ret;

    if (pthread_create(&worker_thread, NULL, thread_func, NULL) != 0) {
        perror("pthread_create");
        return 1;
    }

    // 1. Get the thread's specific CPU clock ID
    ret = pthread_getcpuclockid(worker_thread, &thread_clock_id);

    if (ret != 0) {
        // Error handling based on known return codes
        if (ret == ENOENT) {
            fprintf(stderr, "Error: Per-thread CPU clocks unsupported.\n");
        } else {
            fprintf(stderr, "Error retrieving clock ID: %s\n", strerror(ret));
        }
        pthread_join(worker_thread, NULL); // Cleanup
        return 1;
    }

    // 2. Read the starting CPU time for the thread
    if (clock_gettime(thread_clock_id, &ts_start) == -1) {
        perror("clock_gettime start");
        pthread_join(worker_thread, NULL);
        return 1;
    }

    printf("Successfully retrieved clock ID. Waiting for thread completion...\n");

    pthread_join(worker_thread, NULL);

    // 3. Read the final CPU time for the thread
    if (clock_gettime(thread_clock_id, &ts_end) == -1) {
        perror("clock_gettime end");
        return 1;
    }

    // Calculate and print the CPU time consumed by the thread
    double elapsed_sec = (double)(ts_end.tv_sec - ts_start.tv_sec) +
                         (double)(ts_end.tv_nsec - ts_start.tv_nsec) / 1000000000.0;

    printf("\nThread CPU time consumed: %.6f seconds\n", elapsed_sec);

    return 0;
}
